def transform(g):
    import copy
    g=[row[:] for row in g]; H,W=len(g),len(g[0])
    col=c0=0
    # find block color and bbox
    from collections import Counter
    cnt=Counter(x for r in g for x in r)
    block=[k for k in cnt if k not in (0,) and cnt[k]>4]
    B=block[0]; M=[k for k in cnt if k not in (0,B)][0]
    cells=[(r,c) for r in range(H) for c in range(W) if g[r][c]==B]
    r0=min(r for r,_ in cells); r1=max(r for r,_ in cells)
    c0=min(c for _,c in cells); c1=max(c for _,c in cells)
    markers=[(r,c) for r in range(H) for c in range(W) if g[r][c]==M]
    out=[row[:] for row in g]
    # rows of block: extend
    for r in range(r0,r1+1):
        ms=[c for rr,c in markers if rr==r]
        if not ms:
            for c in range(W): out[r][c]=B
        else:
            for c in ms:
                if c<c0:
                    for cc in range(c1+1,W): out[r][cc]=B
                else:
                    for cc in range(0,c0): out[r][cc]=B
    # markers above/below -> stripes at c-1,c+1 within [c0,c1]
    def stripes(rlo,rhi,ms):
        cols=set()
        for (r,c) in ms:
            for cc in (c-1,c+1):
                if c0<=cc<=c1 and all(cc!=mc for _,mc in ms): cols.add(cc)
        for r in range(rlo,rhi+1):
            for c in cols:
                if out[r][c]==0: out[r][c]=B
    above=[(r,c) for r,c in markers if r<r0]
    below=[(r,c) for r,c in markers if r>r1]
    if above:
        stripes(0,r0-1,above)
    else:
        for c in range(c0,c1+1): out[r0-1][c]=B   # grow up when nothing above
    if below:
        stripes(r1+1,H-1,below)
    else:
        if r1+1<H:
            for c in range(c0,c1+1): out[r1+1][c]=B
    return out

